import { Accordion, AccordionDetails, AccordionSummary, Typography } from "@owlky/react";
import { useState } from "react";

const PANELS = [["General settings","Notifications, language and time zone"],["Users","Who can see and edit this workspace"],["Advanced settings","Webhooks, exports and API keys"],["Personal data","Download or delete your data"]] as const;

export function ControlledExample() {
  const [expanded, setExpanded] = useState<string | false>(false);
  return PANELS.map(([panel, summary]) => (
    <Accordion
      key={panel}
      name="controlled"
      expanded={expanded === panel}
      onChange={(open) => setExpanded(open ? panel : false)}
    >
      <AccordionSummary>
        <Typography variant="subtitle1" component="span">
          {panel}
        </Typography>
        <Typography variant="body2" component="span" color="textSecondary">
          {summary}
        </Typography>
      </AccordionSummary>
      <AccordionDetails>…</AccordionDetails>
    </Accordion>
  ));
}

