      <NavigationControl position="top-right" />
      {/* promoteId: the state's name is the feature id the regions join on. */}
      <Source id="population" type="geojson" data={US_STATES} promoteId="name">
        <Layer {...fill} />
        <Layer {...outline} />
      </Source>
      <MapRegions
