import {
  Button,
  Menu,
  MenuItem,
  moveBetweenLists,
  Scrollbar,
  Sortable,
  Typography,
} from "@owlky/react";
import { useState } from "react";

type Task = { id: string; title: string };

const COLUMNS = [
  { id: "kanban-todo", title: "To do" },
  { id: "kanban-progress", title: "In progress" },
  { id: "kanban-review", title: "In review" },
  { id: "kanban-done", title: "Done" },
];

const INITIAL: Record<string, Task[]> = {
  "kanban-todo": [
    { id: "task-1", title: "Write the brief" },
    { id: "task-2", title: "Book the venue" },
    { id: "task-3", title: "Send invitations" },
  ],
  "kanban-progress": [
    { id: "task-4", title: "Design the poster" },
    { id: "task-5", title: "Plan the budget" },
  ],
  "kanban-review": [{ id: "task-6", title: "Pick the menu" }],
  "kanban-done": [],
};

/**
 * "Move to" choices for one task: every column (a single-pointer alternative to dragging). Choosing
 * the column the task is in does nothing.
 */
function MoveMenu({ task }: { task: Task }) {
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const menu = `${task.id}-menu`;
  return (
    <>
      <Button
        id={`${task.id}-move`}
        size="sm"
        aria-label={`Move ${task.title}`}
        aria-haspopup="menu"
        aria-expanded={anchor !== null}
        aria-controls={menu}
        onClick={(event) => setAnchor(anchor ? null : event.currentTarget)}
      >
        Move
      </Button>
      <Menu
        id={menu}
        aria-labelledby={`${task.id}-move`}
        open={anchor !== null}
        anchorEl={anchor}
        onOpenChange={() => setAnchor(null)}
      >
        {COLUMNS.map((other) => (
          <MenuItem key={other.id} data-ok-sortable-move-to={other.id}>
            {`Move to ${other.title}`}
          </MenuItem>
        ))}
      </Menu>
    </>
  );
}

/** A board: four lists in one group, so tasks move between columns. */
export function KanbanDemo() {
  const [lists, setLists] = useState(INITIAL);
  return (
    <Scrollbar aria-label="Board">
      <div className="sb-kanban">
        {COLUMNS.map((column) => (
          <section key={column.id} aria-labelledby={`${column.id}-title`}>
            <Typography variant="h6" component="h3" id={`${column.id}-title`}>
              {column.title}
            </Typography>
            <Sortable
              id={column.id}
              group="kanban"
              layout="vertical"
              aria-label={column.title}
              items={lists[column.id] ?? []}
              getKey={(task) => task.id}
              getItemLabel={(task) => task.title}
              renderItem={(task) => (
                <div className="sb-kanban-card">
                  <Typography variant="subtitle2" component="span">
                    {task.title}
                  </Typography>
                  <MoveMenu task={task} />
                </div>
              )}
              onReorder={(items) => setLists((all) => ({ ...all, [column.id]: items }))}
              onTransfer={(event) => setLists((all) => moveBetweenLists(all, event))}
            />
          </section>
        ))}
      </div>
    </Scrollbar>
  );
}

import { Scrollbar, Sortable, Typography } from "@owlky/react";
import { useState } from "react";

type Widget = { id: string; title: string; pinned?: boolean };

const WIDGETS: Widget[] = [
  { id: "widget-overview", title: "Overview", pinned: true },
  { id: "widget-sales", title: "Sales" },
  { id: "widget-orders", title: "Orders" },
  { id: "widget-visitors", title: "Visitors" },
  { id: "widget-reviews", title: "Reviews" },
];

/** A pinned first item that can't move, and a status line that follows the drag events. */
export function DisabledItemsDemo() {
  const [widgets, setWidgets] = useState(WIDGETS);
  const [status, setStatus] = useState("Move a widget.");
  return (
    <>
      <Scrollbar aria-label="Dashboard widgets list">
        <Sortable
          id="sortable-disabled"
          layout="vertical"
          aria-label="Dashboard widgets"
          items={widgets}
          getKey={(widget) => widget.id}
          getItemLabel={(widget) => widget.title}
          isItemDisabled={(widget) => widget.pinned === true}
          renderItem={(widget) => (
            <Typography variant="subtitle2" component="span">
              {widget.pinned ? `${widget.title} (pinned)` : widget.title}
            </Typography>
          )}
          onReorder={setWidgets}
          onDragStart={({ item }) => setStatus(`Moving ${item.title}.`)}
          onDragEnd={({ item, index }) =>
            setStatus(`${item.title} is now at position ${index + 1}.`)
          }
          onDragCancel={({ item }) => setStatus(`${item.title} went back.`)}
        />
      </Scrollbar>
      <Typography
        id="sortable-disabled-status"
        variant="body2"
        component="p"
        color="textSecondary"
        role="status"
      >
        {status}
      </Typography>
    </>
  );
}

import { Button, Paper, Step, StepLabel, Stepper, Typography } from "@owlky/react";
import { useState } from "react";

const STEPS = [
  { label: "Choose a plan", text: "Pick the plan and the billing period that suit your team." },
  {
    label: "Add details",
    optional: "Optional",
    text: "Name the project and invite the people who will work on it.",
  },
  { label: "Review and confirm", text: "Check the summary, then confirm to create the project." },
];

/** A linear stepper: Next completes the current step, Back returns to the previous one. */
export function HorizontalDemo({ alternativeLabel = false }: { alternativeLabel?: boolean }) {
  const [active, setActive] = useState(0);
  return (
    <div className="sb-stepper-demo">
      <Stepper activeStep={active} alternativeLabel={alternativeLabel} aria-label="Project setup">
        {STEPS.map((step) => (
          <Step key={step.label}>
            <StepLabel optional={step.optional}>{step.label}</StepLabel>
          </Step>
        ))}
      </Stepper>
      <Paper elevation={0} className="sb-stepper-panel">
        {active < STEPS.length ? (
          <Typography variant="body2">{STEPS[active]?.text}</Typography>
        ) : (
          <div>
            <Typography variant="body2">All steps completed. Your project is ready.</Typography>
            <Button color="inherit" onClick={() => setActive(0)}>
              Reset
            </Button>
          </div>
        )}
      </Paper>
      <div className="sb-stepper-actions">
        <Button color="inherit" disabled={active === 0} onClick={() => setActive(active - 1)}>
          Back
        </Button>
        <Button
          variant="contained"
          color="inherit"
          onClick={() => setActive(Math.min(active + 1, STEPS.length))}
        >
          Next
        </Button>
      </div>
    </div>
  );
}

