  return (
    <>
      <FormControlLabel
        label="All drinks"
        control={
          <Checkbox
            checked={checked}
            indeterminate={indeterminate}
            onChange={(next) => setSelected(next ? drinks : [])}
          />
        }
      />
      {drinks.map((drink) => (
        <FormControlLabel
          key={drink}
          label={drink}
          control={
            <Checkbox
              id={drink.toLowerCase()}
              checked={selected.includes(drink)}
              onChange={(next) =>
                setSelected(next ? [...selected, drink] : selected.filter((d) => d !== drink))
              }
            />
          }
        />
      ))}
    </>
  );
}

